<?php

namespace App\Models;

use App\Support\Lookups;
use Illuminate\Database\Eloquent\Model;

/**
 * `tours` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $TourID
 * @property string|null $TourName
 * @property string|null $TourDescription
 * @property float|null $TourDurationHours
 * @property float|null $TourDurationDays
 * @property int|null $order
 * @property string|null $DestinationType
 * @property string|null $Files
 * @property int|null $Tickets
 */
class Tour extends Model
{
    protected $table = 'tours';

    protected $primaryKey = 'TourID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'TourID' => 'integer',
            'TourDurationHours' => 'float',
            'TourDurationDays' => 'float',
            'order' => 'integer',
            'Tickets' => 'integer',
        ];
    }

    protected static function booted(): void
    {
        static::saving(function (Tour $tour): void {
            $tour->TourDescription ??= '';
        });
        // Places feed the From/To suggestions everywhere.
        static::saved(fn () => Lookups::flush());
    }
}
